path = r'C:\Users\王瑜\WorkBuddy\2026-08-02-17-28-50\deploy\index.html'
with open(path, 'r', encoding='utf-8') as f:
    html = f.read()

modalJs = '''\nlet currentFundHistory = [];\nlet currentFundChartRange = 180;\n\nfunction showFundDetail(code) {\n  const fund = Store.funds?.find(f => f.code === code);\n  if (!fund) { showToast('未找到基金数据'); return; }\n  const modal = document.getElementById('fundDetailModal');\n  document.getElementById('fdName').textContent = fund.name || '--';\n  document.getElementById('fdCode').textContent = fund.code ? (fund.code + ' · ' + (fund.type||'--')) : '--';\n  document.getElementById('fdNav').textContent = fund.nav ? fund.nav.toFixed(4) : '--';\n  const ret1yEl = document.getElementById('fdRet1y');\n  if (fund.ret1y !== undefined && fund.ret1y !== null) {\n    ret1yEl.textContent = (fund.ret1y >= 0 ? '+' : '') + fund.ret1y.toFixed(2) + '%';\n    ret1yEl.className = 'fund-ret ' + (fund.ret1y >= 0 ? 'up' : 'down');\n  } else {\n    ret1yEl.textContent = '--';\n    ret1yEl.className = '';\n  }\n  document.getElementById('fdInfo').innerHTML = `\n    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">\n      <div>近1周: <span class="${colorV(fund.ret1w)}">${signV(fund.ret1w)}${(fund.ret1w||0).toFixed(2)}%</span></div>\n      <div>近1月: <span class="${colorV(fund.ret1m)}">${signV(fund.ret1m)}${(fund.ret1m||0).toFixed(2)}%</span></div>\n      <div>近3月: <span class="${colorV(fund.ret3m)}">${signV(fund.ret3m)}${(fund.ret3m||0).toFixed(2)}%</span></div>\n      <div>近6月: <span class="${colorV(fund.ret6m)}">${signV(fund.ret6m)}${(fund.ret6m||0).toFixed(2)}%</span></div>\n    </div>\n    <div style="margin-top:8px;font-size:10px;color:var(--text-muted);">数据来源：东方财富基金排行API，历史净值仅供参考</div>\n  `;\n  modal.style.display = 'flex';\n  currentFundChartRange = 180;\n  loadFundHistory(code);\n}\nfunction closeFundDetail() {\n  document.getElementById('fundDetailModal').style.display = 'none';\n}\nfunction setFundChartRange(days) {\n  currentFundChartRange = days;\n  drawFundChart();\n}\nasync function loadFundHistory(code) {\n  currentFundHistory = [];\n  try {\n    const d = await jsonp('https://api.fund.eastmoney.com/f10/lsjz?fundCode='+code+'&pageIndex=1&pageSize=400');\n    if (d?.Data?.LSJZList) {\n      currentFundHistory = d.Data.LSJZList.map(it => ({\n        date: it.FSRQ,\n        nav: parseFloat(it.DWJZ) || 0\n      })).filter(x => x.nav > 0).reverse();\n    }\n  } catch(e) {}\n  drawFundChart();\n}\nfunction drawFundChart() {\n  const canvas = document.getElementById('fdChart');\n  if (!canvas || currentFundHistory.length < 2) return;\n  const ctx = canvas.getContext('2d');\n  const w = canvas.width, h = canvas.height;\n  ctx.clearRect(0, 0, w, h);\n  const data = currentFundHistory.slice(-currentFundChartRange);\n  const vals = data.map(d => d.nav);\n  const min = Math.min(...vals), max = Math.max(...vals);\n  const range = max - min || 1;\n  const pad = 10;\n  const start = data[0].nav;\n  const end = data[data.length-1].nav;\n  const isUp = end >= start;\n  ctx.strokeStyle = isUp ? '#e53e3e' : '#38a169';\n  ctx.lineWidth = 2;\n  ctx.beginPath();\n  data.forEach((p, i) => {\n    const x = pad + (i / (data.length - 1)) * (w - pad*2);\n    const y = h - pad - ((p.nav - min) / range) * (h - pad*2);\n    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);\n  });\n  ctx.stroke();\n  ctx.lineTo(w-pad, h-pad);\n  ctx.lineTo(pad, h-pad);\n  ctx.closePath();\n  const grad = ctx.createLinearGradient(0, 0, 0, h);\n  grad.addColorStop(0, isUp ? 'rgba(229,62,62,0.15)' : 'rgba(56,161,105,0.15)');\n  grad.addColorStop(1, 'rgba(255,255,255,0)');\n  ctx.fillStyle = grad;\n  ctx.fill();\n  ctx.fillStyle = '#6b7280';\n  ctx.font = '10px sans-serif';\n  ctx.fillText(min.toFixed(3), 4, h-4);\n  ctx.fillText(max.toFixed(3), 4, 12);\n}\ndocument.getElementById('fundDetailModal').addEventListener('click', function(e){\n  if (e.target === this) closeFundDetail();\n});\n'''

# Insert before </script> that appears just before </body> (the last </script>)
html = html.rsplit('</script>', 1)[0] + modalJs + '</script>' + html.rsplit('</script>', 1)[1]

with open(path, 'w', encoding='utf-8') as f:
    f.write(html)

print('Modal JS added')
